import{_ as t,l as s,o as e,c as n,v as r,p as l,x as o,d as c,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"风险分担","description":"","frontmatter":{"title":"风险分担","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/risk-sharing.md","filePath":"econ/risk-sharing.md","lastUpdated":1789023840000}'),_={name:"econ/risk-sharing.md"};function m(A,a,B,E,d,u){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="风险分担" tabindex="-1">风险分担 <a class="header-anchor" href="#风险分担" aria-label="Permalink to &quot;风险分担&quot;">​</a></h1><div class="epigraph"><p>帕累托最优的保险，是让每个人的边际效用在同一状态下成比例——再保险市场把这条规则标成价格。</p><footer>—— 据 Borch, Equilibrium in a Reinsurance Market, Econometrica, 1962；Wilson, The Theory of Syndicates, Econometrica, 1968 整理</footer></div><p><a href="/econ/complete-span">上一课</a>把完全市场收成 \\(\\mathrm{span}(A)=\\mathbb{R}^S\\)。本课不重写秩与无套利，也不把收益矩阵再排一遍。缺口是：张成只保证任意或有束买得到，没有说出<strong>谁在哪个状态吃多少</strong>才是帕累托。状态依存课已经出现 MRS 对齐；本课把对齐收成 Borch 规则，并标明它依赖完全市场。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两人、有限状态、共同信念 \\(\\pi\\)，合计禀赋 \\(\\omega_s=x_s^A+x_s^B\\)。帕累托要求不存在再分配使一人严格更好、另一人不更差。在期望效用下，这不是「每人各买各的保险」，而是状态之间的共同承担。缺口是 Borch 的一阶条件：存在权重 \\(\\lambda\\gt 0\\)，使对一切 \\(s\\)，</p> \\[\\frac{u_A&#39;(x_s^A)}{u_B&#39;(x_s^B)}=\\lambda, \\]<p>即状态间的边际效用比是常数。等价地，两人的 MRS 对齐，且等于完全市场上的状态价格比 \\(q_s/q_t\\)——上一课的 \\(q\\) 在这里第一次被用来执行分担，而不是只用来定价证券。</p><p>Wilson 的辛迪加：许多风险厌恶者合成一个代表人，\\(u_*\\) 的绝对风险容忍 \\(1/r_A\\) 在加总上等于各人容忍之和（权重合适时）。本课只取这条加总含义，不把代表人写成宏观完整理论。</p><h3 id="公平保险全额投保是-borch-的特例" tabindex="-1">公平保险全额投保是 Borch 的特例 <a class="header-anchor" href="#公平保险全额投保是-borch-的特例" aria-label="Permalink to &quot;公平保险全额投保是 Borch 的特例&quot;">​</a></h3><p>单人对公平定价的可保风险充分投保，来自<a href="/econ/risk-aversion">风险厌恶</a>的凹性。那是「把风险全部交给风险中性的保险人」。Borch 覆盖双方都凹：风险不消失，按 \\(1/r_A\\) 分摊。不要把「最优分担」读成「每人方差最小」——那是均值方差刀刃，不是本课。</p><p><span class="marginnote">共同信念下，Borch 不要求每人持有同一数量。更厌恶的人（\\(r_A\\) 更大）在总量波动里承担更小的份额。异质信念会把分担与投机缠在一起，本课不走。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>完全市场上，每人解 \\(\\max\\mathbb{E}u_i(x^i)\\) s.t. \\(q\\cdot x^i=q\\cdot\\omega^i\\)。一阶条件 \\(\\pi_s u_i&#39;(x_s^i)=\\mu_i q_s\\)。消去 \\(\\mu_i\\) 即 Borch。市场出清 \\(\\sum_i x_s^i=\\omega_s\\) 把总量风险留给加总；个人风险在可保的方向上被对冲掉。</p><p>不完全时，上一课的正交补无法交易，Borch 只在 \\(\\mathrm{span}(A)\\) 的坐标上成立，未张成的冲击各人吞下自己的禀赋。本课主干写完全这一端，把不完全当刀刃。</p>',14)),(e(),l(p,null,{default:o(()=>[h(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPAN%5B%22%E5%AE%8C%E5%85%A8%EF%BC%9Aspan(A)%3DR%5ES%22%5D%20--%3E%20Q%5B%22%E7%8A%B6%E6%80%81%E4%BB%B7%E6%A0%BC%20q%22%5D%0A%20%20Q%20--%3E%20BORCH%5B%22Borch%EF%BC%9Au_A'%2Fu_B'%20%E8%B7%A8%E7%8A%B6%E6%80%81%E5%B8%B8%E6%95%B0%22%5D%0A%20%20BORCH%20--%3E%20WIL%5B%22Wilson%EF%BC%9A%E5%AE%B9%E5%BF%8D%E5%8A%A0%E6%80%BB%22%5D%0A%20%20SPAN%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%A6%82%E7%8E%87%E6%9C%AA%E7%9F%A5%E4%B8%8D%E6%98%AF%E5%90%8C%E4%B8%80%E9%97%AE%E9%A2%98%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>本课不引入道德风险。隐藏行动会让「按状态支付」写不成，分担规则改成信息课的次优合同。也不把再保险写成限价簿上的合约清单。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么边际效用成比例：若某状态里 \\(A\\) 的 \\(u&#39;\\) 相对 \\(B\\) 过高，把一单位消费从 \\(B\\) 挪到 \\(A\\) 可帕累托改进。完全市场提供挪动的工具（复制任意方向）。价格 \\(q_s\\) 高的状态是总量穷的状态：所有凹 \\(u\\) 一起收紧，这与 SOSD/MPS 一致——总量展形伤害所有风险厌恶者，分担改变的是<strong>谁承担多少</strong>，不是展形本身。</p><p>CARA 给出线性分担：每人拿总量的固定份额加一笔状态无关的转移。CRRA 给出对总量的常弹性分担。形状课的函数形式在这里第一次变成可加总的规则。</p><p><span class="marginnote">Borch 1962 的对象是再保险：保险人之间交换风险。规则与 Arrow 证券上的帕累托最优是同一套一阶条件，不必另起「保险哲学」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>异质概率、背景不可保风险、参与约束，都会打断简单的 Borch 常数。模糊下一课会说：没有 \\(\\pi\\) 则没有 \\(\\mathbb{E}u\\) 可分担。主干仍用客观 \\(\\pi\\) 与完全市场。</p><p>加总代表人需要财富分配与形状配合（如 Gorman、CRRA 同权）。Wilson 不是无条件的「市场有一个 \\(u\\)」。也不要把最优分担写成限价簿两边量能匹配——那是微观结构，这里是或有商品的帕累托。</p><p>后课默认：完全市场下的帕累托风险分担即 Borch 规则；不完全则规则只在张成子空间上成立。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>张成保证能买到；Borch 说出帕累托时各状态如何分。</li><li>共同信念下 \\(u_A&#39;/u_B&#39;\\) 跨状态为常数，并由 \\(q\\) 执行。</li><li>双方都凹则风险按容忍分摊，不是消灭风险。</li><li>下一课标明：未知概率不是本课这种风险。</li><li>出处：Borch, <em>Econometrica</em>, 1962；Wilson, <em>Econometrica</em>, 1968。</li></ul>',11))])}const q=t(_,[["render",m]]);export{f as __pageData,q as default};
